index e0eaaefb13d..83448561189 100644
--- a/drivers/platform/x86/acer-wmi.c
+++ b/drivers/platform/x86/acer-wmi.c
@@ -403,6 +403,7 @@ struct quirk_entry {
 	u8 turbo;
