 	u8 gpu_fans;
+	u8 hwmon;
 	u8 predator_v4;
 	u8 pwm;
 };
@@ -421,6 +422,9 @@ static void __init set_quirks(void)
 		interface->capability |= ACER_CAP_TURBO_OC | ACER_CAP_TURBO_LED
 					 | ACER_CAP_TURBO_FAN;
 
+	if (quirks->hwmon)
+		interface->capability |= ACER_CAP_HWMON;
